// App members. Comparison is transient, account-bound and decoded by ImageWorker.
fs::path auditionCompareReference;std::string auditionCompareReferenceRun,auditionCompareScope,auditionCompareChannel,auditionCompareMode;int auditionCompareReferenceIndex=-1;
fs::path auditionComparePaths[2];Com<ID2D1Bitmap> auditionCompareBitmaps[2];bool auditionCompareFailed[2]={false,false};bool auditionCompareNearest[2]={false,false};float auditionImagePercent=0;ULONGLONG auditionCompareNextCheck=0;
void stopAuditionComparison(bool clearReference=false){for(int i=0;i<2;i++){auditionComparePaths[i].clear();auditionCompareBitmaps[i].Reset();auditionCompareFailed[i]=false;}if(clearReference){auditionCompareReference.clear();auditionCompareReferenceRun.clear();auditionCompareReferenceIndex=-1;}}
void checkAuditionComparison(){if(auditionCompareScope!=store->workspaceScope||auditionCompareChannel!=store->active||auditionCompareMode!=str(store->settings,"content_mode","standard"))stopAuditionComparison(true);if(GetTickCount64()>=auditionCompareNextCheck){auditionCompareNextCheck=GetTickCount64()+1000;for(auto& path:auditionComparePaths)if(!path.empty()){std::error_code error;if(!fs::is_regular_file(path,error))stopAuditionComparison();}}}
bool auditionComparing(){checkAuditionComparison();return !auditionComparePaths[0].empty()&&!auditionComparePaths[1].empty();}
void beginAuditionComparison(const fs::path& a,const fs::path& b){for(auto& path:{a,b})if(!fs::is_regular_file(path)||!localOutputAllowed(store->settings,path)||!localImageVisible(store->settings,path)||(!hardcore()&&imageIsHardcore(store->settings,path)))throw std::runtime_error("현재 계정과 모드의 후보 이미지를 선택하세요.");stopAuditionComparison();auditionCompareScope=store->workspaceScope;auditionCompareChannel=store->active;auditionCompareMode=str(store->settings,"content_mode","standard");auditionComparePaths[0]=a;auditionComparePaths[1]=b;focusPreview=true;images.compare(a,b,revision);InvalidateRect(hwnd,nullptr,FALSE);}
std::pair<Rect,Rect> auditionComparisonPanes(Rect r){float x=r.x+8,y=r.y+34,w=std::max(1.f,r.w-16),h=std::max(1.f,r.h-42);if(r.w>=420){float half=(w-8)/2;return {{x,y,half,h},{x+half+8,y,half,h}};}float half=std::max(1.f,(h-8)/2);return {{x,y,w,half},{x,y+half+8,w,half}};}
bool paintAuditionComparison(Rect area){if(!auditionComparing())return false;auto panes=auditionComparisonPanes(area);label(L"후보 비교",{area.x+10,area.y+5,std::max(1.f,area.w-90),24},true);button({area.x+area.w-74,area.y+4,66,24},L"비교 종료",[this]{stopAuditionComparison();});for(int i=0;i<2;i++){auto pane=i?panes.second:panes.first;renderer.box(pane,0x141415,0x3a3a40,5);label(i?L"B":L"A",{pane.x+6,pane.y+2,pane.w-12,18},true);Rect image{pane.x+4,pane.y+23,std::max(1.f,pane.w-8),std::max(1.f,pane.h-27)};if(auditionCompareBitmaps[i])renderer.bitmap(auditionCompareBitmaps[i].Get(),image,auditionCompareNearest[i]);else label(auditionCompareFailed[i]?L"읽기 실패":L"불러오는 중…",image,false,0xccccd0,11);}return true;}
void auditionShowProgress(){checkAuditionComparison();if((!auditionRunning&&!auditionInFlight)||!auditionData||auditionRun.empty()||auditionScope!=store->workspaceScope||auditionChannel!=store->active)return;auto& row=auditionData->run(auditionRun);int done=0;for(auto& item:row["tasks"])done+=str(item,"state")=="completed";auto total=row["tasks"].size();auto prefix=L"[오디션 ";if(status.rfind(prefix,0)==0){auto end=status.find(L"] ");if(end!=std::wstring::npos)status=status.substr(end+2);}status=std::wstring(prefix)+std::to_wstring(done)+L"/"+std::to_wstring(total)+L"] "+status;if(total)progress=float(100.*(done+std::clamp(auditionImagePercent,0.f,99.f)/100)/total);}
